\set ON_ERROR_STOP on
-- AD3-139: convergencia sobre la preimagen física H6 posterior a #222.
-- Sustituye prospectivamente AD133 sin declarar instalado AD133. Conserva los
-- diecisiete roles y membresías nominales adicionales y los catorce tipos cuya
-- ACL ya había revocado USAGE a PUBLIC. El orden externo→RPT sigue rechazado
-- por AD126; no se incorpora otra preimagen.
-- Entrada causal: H6/AD132; roles Catálogos, Cat1, Cat2, AD117, Cat3 y
-- AD126 de #222 instaladas una sola vez. AD134/136 son posteriores.
-- Preimagen GLOBAL medida en PG18: función,
-- cuerpo, definición, configuración, propietario, ACL, OID y dependencias;
-- CHECK de audiencias, membresías técnicas y TEMP de PUBLIC. Ninguna huella
-- de las candidatas anteriores sirve para esta postimagen.
-- Sólo cierra search_path pendiente. Las ACL de tipos ya están restringidas.
-- Conserva cuerpos, concesiones nominales, OID, layout, dependencias e historia.
BEGIN;
SET LOCAL search_path = pg_catalog, pg_temp;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';
SELECT pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('vec_autorizacion_atestada_v3:nucleo', 0));
SELECT pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('vec_autorizacion_atestada_v3:migracion:000139', 0));
