"attlen":-1,"attmissingval":null,"attname":"motivo_catalogado_ref","attndims":0,"attnotnull":true,"attnum":4,"attoptions":null,"attstattarget":null,"attstorage":"x","atttypmod":-1},"tipo":"text"},{"collation":"\"default\"","metadatos":{"attacl":null,"attalign":"i","attbyval":false,"attcompression":"","attfdwoptions":null,"attgenerated":"","atthasdef":false,"atthasmissing":false,"attidentity":"","attinhcount":0,"attisdropped":false,"attislocal":true,"attlen":-1,"attmissingval":null,"attname":"acto_ref","attndims":0,"attnotnull":true,"attnum":5,"attoptions":null,"attstattarget":null,"attstorage":"x","atttypmod":-1},"tipo":"text"},{"collation":null,"metadatos":{"attacl":null,"attalign":"d","attbyval":true,"attcompression":"","attfdwoptions":null,"attgenerated":"","atthasdef":true,"atthasmissing":false,"attidentity":"","attinhcount":0,"attisdropped":false,"attislocal":true,"attlen":8,"attmissingval":null,"attname":"registrada_en","attndims":0,"attnotnull":true,"attnum":6,"attoptions":null,"attstattarget":null,"attstorage":"p","atttypmod":6},"tipo":"timestamp(6) with time zone"}],"metadatos":{"typalign":"d","typanalyze":"-","typbasetype":"0","typbyval":false,"typcategory":"C","typcollation":"0","typdefault":null,"typdefaultbin":null,"typdelim":",","typelem":"0","typinput":"record_in","typisdefined":true,"typispreferred":false,"typlen":-1,"typmodin":"-","typmodout":"-","typname":"revocacion_raiz","typndims":0,"typnotnull":false,"typoutput":"record_out","typreceive":"record_recv","typsend":"record_send","typstorage":"x","typsubscript":"-","typtype":"c","typtypmod":-1},"nombre":"revocacion_raiz","propietario":"vec_autorizacion_atestada_v3_propietario"}]}$frontera_a$::pg_catalog.jsonb;
    frontera_actual pg_catalog.jsonb;
    frontera_esperada pg_catalog.jsonb;
    tipos_public_a pg_catalog.jsonb := $tipos_public_a$[]$tipos_public_a$::pg_catalog.jsonb;
    tipos_public_elegidos pg_catalog.jsonb;
    tipos_antes pg_catalog.jsonb;
    tipo pg_catalog.record;
    acl_antes pg_catalog.jsonb;
    acl_despues pg_catalog.jsonb;
    tipo_dependencias pg_catalog.jsonb;
    matriz_elegida pg_catalog.jsonb;
    pendientes_elegidos pg_catalog.jsonb;
    actual pg_catalog.jsonb;
    filas pg_catalog.jsonb;
    e pg_catalog.jsonb;
    f pg_catalog.oid;
    antes pg_catalog.pg_proc%ROWTYPE;
    despues pg_catalog.pg_proc%ROWTYPE;
    dependencias_antes pg_catalog.jsonb;
    dependencias_despues pg_catalog.jsonb;
    tipo_deps_despues pg_catalog.jsonb;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles
                   WHERE rolname = current_user AND rolsuper)
       OR pg_catalog.current_setting('server_version_num')::pg_catalog.int4
          NOT BETWEEN 180000 AND 189999
       OR pg_catalog.current_setting('transaction_read_only') <> 'off'
       OR nucleo IS NULL THEN
        RAISE EXCEPTION 'AD3-139: migrador, PG18 o prefijo #222 ausente'
          USING ERRCODE = '55000';
    END IF;
    SELECT p.prosrc, p.proconfig INTO STRICT cuerpo, configuracion
      FROM pg_catalog.pg_proc AS p WHERE p.oid = nucleo;
    -- AD118 añade el despacho Usuarios después de #222. Su cuerpo completo
    -- pertenece a la matriz del linaje; la huella post-AD126 no lo sustituye.
    IF configuracion IS DISTINCT FROM
          ARRAY['search_path=pg_catalog, pg_temp', 'lock_timeout=2s'] THEN
        RAISE EXCEPTION 'AD3-139: configuración del núcleo post-#222 incompatible'
          USING ERRCODE = '55000';
    END IF;
    -- Antes de permitir la postimagen, cotejar también en esta transacción el
    -- CHECK de audiencias, ACL de tipos compuestos, membresías y TEMP/PUBLIC
    -- medidos en A. La prueba focal obtiene el inventario íntegro.
    IF matriz_a IS NULL OR pendientes_a IS NULL
       OR frontera_a IS NULL OR tipos_public_a IS NULL THEN
        RAISE EXCEPTION 'AD3-139: matrices globales PG18 ausentes'
          USING ERRCODE = '55000';
    END IF;
    IF pg_catalog.jsonb_typeof(matriz_a) IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(pendientes_a) IS DISTINCT FROM 'array'
       OR (SELECT pg_catalog.count(DISTINCT (x->>'firma'))
           FROM pg_catalog.jsonb_array_elements(matriz_a) x)
          IS DISTINCT FROM pg_catalog.jsonb_array_length(matriz_a) THEN
        RAISE EXCEPTION 'AD3-139: matrices globales incompletas o duplicadas'
          USING ERRCODE='55000';
    END IF;
SELECT pg_catalog.jsonb_agg(ficha ORDER BY ficha->>'firma') INTO actual FROM (
 SELECT pg_catalog.jsonb_build_object(
  'firma',p.oid::pg_catalog.regprocedure::pg_catalog.text,
  'sha_prosrc',pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p.prosrc,'UTF8')),'hex'),
  'sha_definicion',pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.pg_get_functiondef(p.oid),'UTF8')),'hex'),
  'owner',pg_catalog.pg_get_userbyid(p.proowner),'language',l.lanname,
  'argtypes',(SELECT pg_catalog.jsonb_agg(pg_catalog.format_type(x,NULL) ORDER BY i)
       FROM pg_catalog.unnest(p.proargtypes::pg_catalog.oid[]) WITH ORDINALITY AS t(x,i)),
  'allargtypes',(SELECT pg_catalog.jsonb_agg(pg_catalog.format_type(x,NULL) ORDER BY i)
       FROM pg_catalog.unnest(p.proallargtypes) WITH ORDINALITY AS t(x,i)),
  'return',pg_catalog.format_type(p.prorettype,NULL),
  'variadic',CASE WHEN p.provariadic=0 THEN NULL ELSE pg_catalog.format_type(p.provariadic,NULL) END,
  'support',CASE WHEN p.prosupport=0 THEN NULL ELSE p.prosupport::pg_catalog.regproc::pg_catalog.text END,
  'pg_proc',pg_catalog.to_jsonb(p)-ARRAY['oid','pronamespace','proowner','prolang','proargtypes','proallargtypes','prorettype','provariadic','prosupport','prosrc','proacl'],
  'acl_effective',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
       'grantee',coalesce(gr.rolname,'PUBLIC'),'grantor',go.rolname,
       'privilege',a.privilege_type,'grantable',a.is_grantable)
       ORDER BY coalesce(gr.rolname,'PUBLIC'),go.rolname,a.privilege_type,a.is_grantable)
       FROM pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) AS a
       LEFT JOIN pg_catalog.pg_roles AS gr ON gr.oid=a.grantee
       LEFT JOIN pg_catalog.pg_roles AS go ON go.oid=a.grantor),'[]'::pg_catalog.jsonb),
  'pg_depend',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
       'class',d.classid::pg_catalog.regclass::pg_catalog.text,'objsubid',d.objsubid,
       'refclass',d.refclassid::pg_catalog.regclass::pg_catalog.text,'refobjsubid',d.refobjsubid,
       'deptype',d.deptype,'target',pg_catalog.to_jsonb(i))
       ORDER BY d.classid::pg_catalog.regclass::pg_catalog.text,d.objsubid,
          d.refclassid::pg_catalog.regclass::pg_catalog.text,d.refobjsubid,d.deptype,i.identity)
       FROM pg_catalog.pg_depend AS d CROSS JOIN LATERAL
          pg_catalog.pg_identify_object(d.refclassid,d.refobjid,d.refobjsubid) AS i
       WHERE d.classid='pg_catalog.pg_proc'::pg_catalog.regclass AND d.objid=p.oid),'[]'::pg_catalog.jsonb),
  'pg_shdepend',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
       'class',d.classid::pg_catalog.regclass::pg_catalog.text,'objsubid',d.objsubid,
       'refclass',d.refclassid::pg_catalog.regclass::pg_catalog.text,'refobjsubid',0,
       'deptype',d.deptype,'target',pg_catalog.to_jsonb(i))
       ORDER BY d.classid::pg_catalog.regclass::pg_catalog.text,d.objsubid,
          d.refclassid::pg_catalog.regclass::pg_catalog.text,d.deptype,i.identity)
       FROM pg_catalog.pg_shdepend AS d CROSS JOIN LATERAL
          pg_catalog.pg_identify_object(d.refclassid,d.refobjid,0) AS i
       WHERE d.classid='pg_catalog.pg_proc'::pg_catalog.regclass AND d.objid=p.oid
          AND d.dbid=(SELECT oid FROM pg_catalog.pg_database WHERE datname=pg_catalog.current_database())),
       '[]'::pg_catalog.jsonb)
 ) AS ficha FROM pg_catalog.pg_proc AS p
 JOIN pg_catalog.pg_language AS l ON l.oid=p.prolang
 WHERE p.pronamespace=pg_catalog.to_regnamespace('vec_autorizacion_atestada_v3')
) AS conjunto;
    IF pg_catalog.jsonb_array_length(actual) IS DISTINCT FROM
       pg_catalog.jsonb_array_length(matriz_a)
       OR (SELECT pg_catalog.count(*) FROM pg_catalog.pg_proc AS p
           WHERE p.pronamespace=pg_catalog.to_regnamespace(
             'vec_autorizacion_atestada_v3'))
          IS DISTINCT FROM pg_catalog.jsonb_array_length(matriz_a)
       OR actual IS DISTINCT FROM matriz_a THEN
        RAISE EXCEPTION 'AD3-139: preimagen global incompatible'
          USING ERRCODE = '55000';
    END IF;
SELECT ficha INTO frontera_actual FROM (
 SELECT pg_catalog.jsonb_build_object(
  'audiencias',(SELECT pg_catalog.jsonb_build_object(
    'definicion',pg_catalog.pg_get_constraintdef(c.oid,true),
    'metadatos',pg_catalog.to_jsonb(c)-ARRAY['oid','connamespace','conrelid','conbin'])
    FROM pg_catalog.pg_constraint AS c
    WHERE c.conrelid=pg_catalog.to_regclass('vec_autorizacion_atestada_v3.clave_capacidad_version')
       AND c.conname='clave_capacidad_version_audiencia_consumo_check'),
  'tipos',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'nombre',t.typname,'propietario',pg_catalog.pg_get_userbyid(t.typowner),
    'metadatos',pg_catalog.to_jsonb(t)-ARRAY['oid','typnamespace','typowner','typrelid','typarray','typacl'],
    'atributos',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
       'metadatos',pg_catalog.to_jsonb(a)-ARRAY['attrelid','atttypid','attcollation'],
       'tipo',pg_catalog.format_type(a.atttypid,a.atttypmod),
       'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::pg_catalog.regcollation::pg_catalog.text END)
       ORDER BY a.attnum) FROM pg_catalog.pg_attribute AS a
       WHERE a.attrelid=t.typrelid AND a.attnum>0),'[]'::pg_catalog.jsonb),
    'acl',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
       'grantee',coalesce(gr.rolname,'PUBLIC'),'grantor',go.rolname,
       'privilege',a.privilege_type,'grantable',a.is_grantable)
       ORDER BY coalesce(gr.rolname,'PUBLIC'),go.rolname,a.privilege_type,a.is_grantable)
       FROM pg_catalog.aclexplode(coalesce(t.typacl,pg_catalog.acldefault('T',t.typowner))) AS a
       LEFT JOIN pg_catalog.pg_roles AS gr ON gr.oid=a.grantee
       LEFT JOIN pg_catalog.pg_roles AS go ON go.oid=a.grantor),'[]'::pg_catalog.jsonb)
    ) ORDER BY t.typname) FROM pg_catalog.pg_type AS t
    WHERE t.typnamespace=pg_catalog.to_regnamespace('vec_autorizacion_atestada_v3') AND t.typtype='c'),
  'membresias',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'rol',g.rolname,'miembro',m.rolname,'otorgante',r.rolname,
    'admin',a.admin_option,'inherit',a.inherit_option,'set',a.set_option)
    ORDER BY g.rolname,m.rolname,r.rolname)
    FROM pg_catalog.pg_auth_members AS a
    JOIN pg_catalog.pg_roles AS g ON g.oid=a.roleid
    JOIN pg_catalog.pg_roles AS m ON m.oid=a.member
    JOIN pg_catalog.pg_roles AS r ON r.oid=a.grantor
    WHERE pg_catalog.left(g.rolname,4)='vec_' OR pg_catalog.left(m.rolname,4)='vec_'),
    '[]'::pg_catalog.jsonb),
  'roles',(SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r)-ARRAY['oid','rolpassword'] ORDER BY r.rolname)
    FROM pg_catalog.pg_roles AS r WHERE pg_catalog.left(r.rolname,4)='vec_'),
  'public_temp',(SELECT coalesce(pg_catalog.bool_or(a.grantee=0 AND a.privilege_type='TEMPORARY'),false)
    FROM pg_catalog.pg_database AS d LEFT JOIN LATERAL
       pg_catalog.aclexplode(coalesce(d.datacl,pg_catalog.acldefault('d',d.datdba))) AS a ON true
    WHERE d.datname=pg_catalog.current_database())
 ) AS ficha
) AS limites;
    IF frontera_actual->'audiencias' IS NULL
       OR frontera_actual->'audiencias'='null'::pg_catalog.jsonb
       OR frontera_actual->>'public_temp' IS DISTINCT FROM 'false'
       OR frontera_actual IS DISTINCT FROM frontera_a THEN
       RAISE EXCEPTION 'AD3-139: CHECK, tipos, membresías o TEMP incompatibles'
         USING ERRCODE='55000';
    END IF;
    matriz_elegida := matriz_a;
    pendientes_elegidos := pendientes_a;
    IF (SELECT pg_catalog.count(DISTINCT x)
        FROM pg_catalog.jsonb_array_elements_text(pendientes_elegidos) x)
        IS DISTINCT FROM pg_catalog.jsonb_array_length(pendientes_elegidos)
       OR (SELECT pg_catalog.jsonb_agg(p.oid::pg_catalog.regprocedure::pg_catalog.text
             ORDER BY p.oid::pg_catalog.regprocedure::pg_catalog.text)
           FROM pg_catalog.pg_proc p
           WHERE p.pronamespace=pg_catalog.to_regnamespace('vec_autorizacion_atestada_v3')
             AND p.proconfig @> ARRAY['search_path=pg_catalog'])
          IS DISTINCT FROM
          (SELECT pg_catalog.jsonb_agg(x ORDER BY x)
           FROM pg_catalog.jsonb_array_elements_text(pendientes_elegidos) x)
       OR EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements_text(pendientes_elegidos) AS x(firma)
               WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(matriz_elegida) AS m(obj)
                                 WHERE m.obj->>'firma'=x.firma))
       OR EXISTS (SELECT 1 FROM pg_catalog.pg_proc AS p
                  CROSS JOIN LATERAL pg_catalog.aclexplode(coalesce(
                    p.proacl,pg_catalog.acldefault('f',p.proowner))) AS a
                  WHERE p.pronamespace=pg_catalog.to_regnamespace('vec_autorizacion_atestada_v3')
                    AND (a.grantee=0 OR p.proowner<>
                      'vec_autorizacion_atestada_v3_propietario'::pg_catalog.regrole))
 THEN
       RAISE EXCEPTION 'AD3-139: firmas pendientes, propietario o ACL incompatibles'
         USING ERRCODE='55000';
    END IF;
 -- Lista vacía porque ningún tipo conserva PUBLIC USAGE en esta preimagen.
 tipos_public_elegidos:=tipos_public_a;
 IF pg_catalog.jsonb_typeof(tipos_public_elegidos) IS DISTINCT FROM 'array'
    OR (SELECT coalesce(pg_catalog.jsonb_agg(t.typname ORDER BY t.typname), '[]'::pg_catalog.jsonb)
        FROM pg_catalog.pg_type t WHERE t.typnamespace=pg_catalog.to_regnamespace('vec_autorizacion_atestada_v3')
        AND t.typtype='c' AND EXISTS (SELECT 1 FROM pg_catalog.aclexplode(coalesce(t.typacl,pg_catalog.acldefault('T',t.typowner))) a WHERE a.grantee=0))
       IS DISTINCT FROM tipos_public_elegidos
    OR EXISTS (SELECT 1 FROM pg_catalog.pg_type t
        CROSS JOIN LATERAL pg_catalog.aclexplode(coalesce(t.typacl,pg_catalog.acldefault('T',t.typowner))) a
        WHERE t.typnamespace=pg_catalog.to_regnamespace('vec_autorizacion_atestada_v3') AND t.typtype='c'
        AND (t.typowner<>'vec_autorizacion_atestada_v3_propietario'::pg_catalog.regrole
          OR (a.grantee=0 AND (a.privilege_type<>'USAGE' OR a.is_grantable)))) THEN
  RAISE EXCEPTION 'AD3-139: lista de cierre de tipos incompatible' USING ERRCODE='55000';
 END IF;
 frontera_esperada:=pg_catalog.jsonb_set(frontera_actual,'{tipos}',
  (SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_set(t,'{acl}',
      (SELECT coalesce(pg_catalog.jsonb_agg(a ORDER BY a->>'grantee',a->>'grantor',a->>'privilege',a->>'grantable'),'[]'::pg_catalog.jsonb)
       FROM pg_catalog.jsonb_array_elements(t->'acl') a WHERE a->>'grantee'<>'PUBLIC')) ORDER BY t->>'nombre')
   FROM pg_catalog.jsonb_array_elements(frontera_actual->'tipos') t));
 SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(t) ORDER BY t.oid) INTO tipos_antes
 FROM pg_catalog.pg_type t WHERE t.typnamespace=pg_catalog.to_regnamespace('vec_autorizacion_atestada_v3') AND t.typtype='c';
 SELECT pg_catalog.jsonb_build_object(
  'locales',(SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(d) ORDER BY d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.refobjsubid,d.deptype)
    FROM pg_catalog.pg_depend d WHERE d.classid='pg_catalog.pg_type'::pg_catalog.regclass AND d.objid IN(SELECT (x->>'oid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements(tipos_antes) x)),
  'compartidas',(SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(d) ORDER BY d.dbid,d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.deptype)
    FROM pg_catalog.pg_shdepend d WHERE d.classid='pg_catalog.pg_type'::pg_catalog.regclass AND d.dbid=(SELECT oid FROM pg_catalog.pg_database WHERE datname=pg_catalog.current_database())
    AND d.objid IN(SELECT (x->>'oid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements(tipos_antes) x))) INTO tipo_dependencias;
 -- Capturar el catálogo completo con sus OID locales antes del primer ALTER.
 SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(p) ORDER BY p.oid)
 INTO filas FROM pg_catalog.pg_proc p
 WHERE p.oid IN(SELECT pg_catalog.to_regprocedure(x->>'firma') FROM pg_catalog.jsonb_array_elements(matriz_elegida) x);
 SELECT pg_catalog.jsonb_build_object(
 'locales',(SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(d) ORDER BY d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.refobjsubid,d.deptype)
 FROM pg_catalog.pg_depend d WHERE d.classid='pg_catalog.pg_proc'::pg_catalog.regclass
 AND d.objid IN(SELECT (x->>'oid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements(filas) x)),
 'compartidas',(SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(d) ORDER BY d.dbid,d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.deptype)
 FROM pg_catalog.pg_shdepend d WHERE d.classid='pg_catalog.pg_proc'::pg_catalog.regclass
 AND d.dbid=(SELECT oid FROM pg_catalog.pg_database WHERE datname=pg_catalog.current_database())
 AND d.objid IN(SELECT (x->>'oid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements(filas) x))) INTO dependencias_antes;
 FOR e IN SELECT x FROM pg_catalog.jsonb_array_elements(filas) x LOOP
  f:=(e->>'oid')::pg_catalog.oid;
  SELECT p.* INTO STRICT antes FROM pg_catalog.pg_proc p WHERE p.oid=f;
  IF pg_catalog.to_jsonb(antes) IS DISTINCT FROM e THEN
   RAISE EXCEPTION 'AD3-139: preimagen concurrente incompatible' USING ERRCODE='55000';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements_text(pendientes_elegidos) x
                WHERE x=f::pg_catalog.regprocedure::pg_catalog.text) THEN
   IF NOT (antes.proconfig @> ARRAY['search_path=pg_catalog, pg_temp']) THEN
    RAISE EXCEPTION 'AD3-139: función fuera del cambio no cerrada' USING ERRCODE='55000';
   END IF;
   CONTINUE; -- AD126 ya cerró el núcleo: no se reaplica el ALTER.
  END IF;
  IF NOT (antes.proconfig @> ARRAY['search_path=pg_catalog']) THEN
   RAISE EXCEPTION 'AD3-139: search_path pendiente incompatible' USING ERRCODE='55000';
  END IF;
  SELECT pg_catalog.array_agg(CASE WHEN opcion='search_path=pg_catalog' THEN 'search_path=pg_catalog, pg_temp' ELSE opcion END ORDER BY indice)
  INTO configuracion FROM pg_catalog.unnest(antes.proconfig) WITH ORDINALITY AS opciones(opcion,indice);
  EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path=pg_catalog,pg_temp',f::pg_catalog.regprocedure);
  SELECT p.* INTO STRICT despues FROM pg_catalog.pg_proc p WHERE p.oid=f;
  IF pg_catalog.to_jsonb(despues)-'proconfig' IS DISTINCT FROM e-'proconfig'
  OR despues.proconfig IS DISTINCT FROM configuracion THEN
   RAISE EXCEPTION 'AD3-139: postimagen incompatible' USING ERRCODE='55000';
  END IF;
 END LOOP;
 -- Preservar las ACL de tipos ya cerradas; sin CASCADE.
 FOR tipo IN SELECT t.* FROM pg_catalog.pg_type t
     WHERE t.typnamespace=pg_catalog.to_regnamespace('vec_autorizacion_atestada_v3') AND t.typtype='c' LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements_text(tipos_public_elegidos) x WHERE x=tipo.typname) THEN
   EXECUTE pg_catalog.format('REVOKE USAGE ON TYPE %s FROM PUBLIC',tipo.oid::pg_catalog.regtype);
  END IF;
  IF (SELECT pg_catalog.to_jsonb(t)-'typacl' FROM pg_catalog.pg_type t WHERE t.oid=tipo.oid)
     IS DISTINCT FROM (SELECT x-'typacl' FROM pg_catalog.jsonb_array_elements(tipos_antes) x WHERE (x->>'oid')::pg_catalog.oid=tipo.oid) THEN
   RAISE EXCEPTION 'AD3-139: metadatos locales de tipo alterados' USING ERRCODE='55000';
  END IF;
 END LOOP;
SELECT ficha INTO frontera_actual FROM (
 SELECT pg_catalog.jsonb_build_object(
  'audiencias',(SELECT pg_catalog.jsonb_build_object(
    'definicion',pg_catalog.pg_get_constraintdef(c.oid,true),
    'metadatos',pg_catalog.to_jsonb(c)-ARRAY['oid','connamespace','conrelid','conbin'])
    FROM pg_catalog.pg_constraint AS c
    WHERE c.conrelid=pg_catalog.to_regclass('vec_autorizacion_atestada_v3.clave_capacidad_version')
       AND c.conname='clave_capacidad_version_audiencia_consumo_check'),
  'tipos',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'nombre',t.typname,'propietario',pg_catalog.pg_get_userbyid(t.typowner),
    'metadatos',pg_catalog.to_jsonb(t)-ARRAY['oid','typnamespace','typowner','typrelid','typarray','typacl'],
    'atributos',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
       'metadatos',pg_catalog.to_jsonb(a)-ARRAY['attrelid','atttypid','attcollation'],
       'tipo',pg_catalog.format_type(a.atttypid,a.atttypmod),
       'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::pg_catalog.regcollation::pg_catalog.text END)
       ORDER BY a.attnum) FROM pg_catalog.pg_attribute AS a
       WHERE a.attrelid=t.typrelid AND a.attnum>0),'[]'::pg_catalog.jsonb),
    'acl',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
       'grantee',coalesce(gr.rolname,'PUBLIC'),'grantor',go.rolname,
       'privilege',a.privilege_type,'grantable',a.is_grantable)
       ORDER BY coalesce(gr.rolname,'PUBLIC'),go.rolname,a.privilege_type,a.is_grantable)
       FROM pg_catalog.aclexplode(coalesce(t.typacl,pg_catalog.acldefault('T',t.typowner))) AS a
       LEFT JOIN pg_catalog.pg_roles AS gr ON gr.oid=a.grantee
       LEFT JOIN pg_catalog.pg_roles AS go ON go.oid=a.grantor),'[]'::pg_catalog.jsonb)
    ) ORDER BY t.typname) FROM pg_catalog.pg_type AS t
    WHERE t.typnamespace=pg_catalog.to_regnamespace('vec_autorizacion_atestada_v3') AND t.typtype='c'),
  'membresias',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'rol',g.rolname,'miembro',m.rolname,'otorgante',r.rolname,
    'admin',a.admin_option,'inherit',a.inherit_option,'set',a.set_option)
    ORDER BY g.rolname,m.rolname,r.rolname)
    FROM pg_catalog.pg_auth_members AS a
    JOIN pg_catalog.pg_roles AS g ON g.oid=a.roleid
    JOIN pg_catalog.pg_roles AS m ON m.oid=a.member
    JOIN pg_catalog.pg_roles AS r ON r.oid=a.grantor
    WHERE pg_catalog.left(g.rolname,4)='vec_' OR pg_catalog.left(m.rolname,4)='vec_'),
    '[]'::pg_catalog.jsonb),
  'roles',(SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r)-ARRAY['oid','rolpassword'] ORDER BY r.rolname)
    FROM pg_catalog.pg_roles AS r WHERE pg_catalog.left(r.rolname,4)='vec_'),
  'public_temp',(SELECT coalesce(pg_catalog.bool_or(a.grantee=0 AND a.privilege_type='TEMPORARY'),false)
    FROM pg_catalog.pg_database AS d LEFT JOIN LATERAL
       pg_catalog.aclexplode(coalesce(d.datacl,pg_catalog.acldefault('d',d.datdba))) AS a ON true
    WHERE d.datname=pg_catalog.current_database())
 ) AS ficha
) AS limites;
 IF frontera_actual IS DISTINCT FROM frontera_esperada THEN
  RAISE EXCEPTION 'AD3-139: frontera posterior alterada fuera del cierre PUBLIC' USING ERRCODE='55000';
 END IF;
 SELECT pg_catalog.jsonb_build_object(
  'locales',(SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(d) ORDER BY d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.refobjsubid,d.deptype)
    FROM pg_catalog.pg_depend d WHERE d.classid='pg_catalog.pg_type'::pg_catalog.regclass AND d.objid IN(SELECT (x->>'oid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements(tipos_antes) x)),
  'compartidas',(SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(d) ORDER BY d.dbid,d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.deptype)
    FROM pg_catalog.pg_shdepend d WHERE d.classid='pg_catalog.pg_type'::pg_catalog.regclass AND d.dbid=(SELECT oid FROM pg_catalog.pg_database WHERE datname=pg_catalog.current_database())
    AND d.objid IN(SELECT (x->>'oid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements(tipos_antes) x))) INTO tipo_deps_despues;
 IF tipo_deps_despues IS DISTINCT FROM tipo_dependencias THEN
  RAISE EXCEPTION 'AD3-139: dependencias de tipos alteradas' USING ERRCODE='55000';
 END IF;
 SELECT pg_catalog.jsonb_build_object(
 'locales',(SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(d) ORDER BY d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.refobjsubid,d.deptype)
 FROM pg_catalog.pg_depend d WHERE d.classid='pg_catalog.pg_proc'::pg_catalog.regclass
 AND d.objid IN(SELECT (x->>'oid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements(filas) x)),
 'compartidas',(SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(d) ORDER BY d.dbid,d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.deptype)
 FROM pg_catalog.pg_shdepend d WHERE d.classid='pg_catalog.pg_proc'::pg_catalog.regclass
 AND d.dbid=(SELECT oid FROM pg_catalog.pg_database WHERE datname=pg_catalog.current_database())
 AND d.objid IN(SELECT (x->>'oid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements(filas) x))) INTO dependencias_despues;
 IF dependencias_despues IS DISTINCT FROM dependencias_antes THEN
  RAISE EXCEPTION 'AD3-139: dependencias alteradas' USING ERRCODE='55000';
 END IF;
END $borrador$;
COMMIT;
